#include <algorithm>
#include <cstdint>
#include <cstring>
#include <filesystem>
#include <fstream>
#include <iostream>
#include <memory>
#include <string>
#include <vector>
#include <unistd.h>
#include <zlib.h>
namespace fs=std::filesystem;
static uint64_t mix64(uint64_t x){x+=0x9e3779b97f4a7c15ULL;x=(x^(x>>30))*0xbf58476d1ce4e5b9ULL;x=(x^(x>>27))*0x94d049bb133111ebULL;return x^(x>>31);}static uint64_t fnv(const std::string&s){uint64_t h=1469598103934665603ULL;for(unsigned char c:s){h^=c;h*=1099511628211ULL;}return h;}static uint32_t p2(uint64_t x){uint64_t p=1;while(p<x)p<<=1;return uint32_t(p);}struct Addr{uint32_t rho;uint64_t fp;};static Addr enc(const std::string&k,uint32_t M){uint64_t h0=mix64(fnv(k)),h1=mix64(h0^0xD6E8FEB86659FD93ULL),h2=mix64(h1^0xA5A35625D3E7E5B9ULL),h3=mix64(h2^0x9E3779B97F4A7C15ULL);return{uint32_t(h0&(M-1)),mix64(h0^(h1<<1)^(h2>>1)^h3)};}
static size_t rss_kb(){std::ifstream f("/proc/self/status");std::string k;size_t v;std::string u;while(f>>k){if(k=="VmRSS:"){f>>v>>u;return v;}std::getline(f,u);}return 0;}
static uint32_t crc(const void*p,size_t n){return uint32_t(crc32(0,(const Bytef*)p,n));}static void u32(std::vector<uint8_t>&b,uint32_t v){for(int i=3;i>=0;--i)b.push_back(uint8_t(v>>(8*i)));}static void u64(std::vector<uint8_t>&b,uint64_t v){for(int i=7;i>=0;--i)b.push_back(uint8_t(v>>(8*i)));}static uint32_t g32(const uint8_t*&p){uint32_t v=0;for(int i=0;i<4;++i)v=(v<<8)|*p++;return v;}static uint64_t g64(const uint8_t*&p){uint64_t v=0;for(int i=0;i<8;++i)v=(v<<8)|*p++;return v;}
struct Slot{uint64_t k=0,v=0;uint32_t d=0;uint8_t state=0;};class RH{std::vector<Slot>s;size_t mask=0;public:RH(){}explicit RH(size_t n){reset(n);}void reset(size_t n){size_t c=8;while(c*.72<std::max<size_t>(1,n))c<<=1;s.assign(c,{});mask=c-1;}void put(uint64_t k,uint64_t v){size_t i=mix64(k)&mask;Slot cur{k,v,0,1};for(;;){auto&x=s[i];if(x.state!=1){x=cur;return;}if(x.k==k){x.v=v;return;}if(x.d<cur.d)std::swap(x,cur);i=(i+1)&mask;++cur.d;}}bool get(uint64_t k,uint64_t&v)const{size_t i=mix64(k)&mask;uint32_t d=0;for(;;){auto&x=s[i];if(x.state==0||x.d<d)return false;if(x.state==1&&x.k==k){v=x.v;return true;}i=(i+1)&mask;++d;}}};
class Index{uint32_t M;std::vector<std::unique_ptr<RH>>p;public:Index(size_t n):M(p2(std::max<uint64_t>(64,(n+255)/256))),p(M){size_t per=(n+M-1)/M+32;for(auto&x:p)x=std::make_unique<RH>(per);}void put(const std::string&k,uint64_t v){auto a=enc(k,M);p[a.rho]->put(a.fp,v);}bool get(const std::string&k,uint64_t&v)const{auto a=enc(k,M);return p[a.rho]->get(a.fp,v);}uint32_t parts()const{return M;}};
static std::vector<uint8_t> make_snapshot(size_t N){std::vector<uint8_t>b;b.insert(b.end(),{'B','D','R','3'});u32(b,3);u64(b,N);u64(b,N);for(size_t i=0;i<N;++i){std::string k="K"+std::to_string(i);u32(b,k.size());u32(b,8);b.insert(b.end(),k.begin(),k.end());u64(b,i);}u32(b,crc(b.data(),b.size()));return b;}
static void write_snapshot(const fs::path&p,size_t N){auto b=make_snapshot(N);std::ofstream f(p,std::ios::binary|std::ios::trunc);f.write((char*)b.data(),b.size());}
static std::unique_ptr<Index> recover_direct(const fs::path&p,size_t&Nout,uint64_t&seq){std::ifstream f(p,std::ios::binary);std::vector<uint8_t>b((std::istreambuf_iterator<char>(f)),{});if(b.size()<28)throw std::runtime_error("short");uint32_t got=(uint32_t(b[b.size()-4])<<24)|(uint32_t(b[b.size()-3])<<16)|(uint32_t(b[b.size()-2])<<8)|b.back();if(crc(b.data(),b.size()-4)!=got)throw std::runtime_error("crc");const uint8_t*q=b.data();if(std::memcmp(q,"BDR3",4))throw std::runtime_error("magic");q+=4;if(g32(q)!=3)throw std::runtime_error("version");seq=g64(q);uint64_t N=g64(q);auto idx=std::make_unique<Index>(N);for(uint64_t i=0;i<N;++i){uint32_t kl=g32(q),vl=g32(q);if(vl!=8)throw std::runtime_error("value size");std::string k((char*)q,kl);q+=kl;uint64_t v=g64(q);idx->put(k,v);}Nout=N;return idx;}
int main(int argc,char**argv){size_t N=argc>1?std::stoull(argv[1]):1000000;fs::path p="v40_snapshot.bdr3";write_snapshot(p,N);size_t before=rss_kb(),nr=0;uint64_t seq=0;auto idx=recover_direct(p,nr,seq);size_t after=rss_kb();uint64_t err=0;for(size_t i=0;i<N;i+=997){uint64_t v=~0ull;if(!idx->get("K"+std::to_string(i),v)||v!=i)++err;}std::cout<<"records,partitions,rss_before_kb,rss_after_kb,rss_delta_kb,sequence,errors,pass\n"<<nr<<','<<idx->parts()<<','<<before<<','<<after<<','<<(after>=before?after-before:0)<<','<<seq<<','<<err<<','<<(nr==N&&seq==N&&err==0)<<"\n";return(nr==N&&seq==N&&err==0)?0:2;}
